int copy_templates_to_skb(struct xfrm_policy *xp, struct sk_buff *skb) {
    int count = 0;
    struct xfrm_tmpl *tmpls = xp->tp;
    int num_tmpls = xp->num_tmpl;
    struct xfrm_user_tmpl *utmpl;
    int i;

    if (num_tmpls == 0)
        return 0;

    utmpl = kcalloc(num_tmpls, sizeof(*utmpl), GFP_ATOMIC);
    if (!utmpl)
        return -ENOMEM;

    for (i = 0; i < num_tmpls; i++) {
        utmpl[i].dir = tmpls[i].dir;
        utmpl[i].mode = tmpls[i].mode;
        utmpl[i].reqid = tmpls[i].reqid;
        utmpl[i].saddr = tmpls[i].saddr;
        utmpl[i].sprio = tmpls[i].prio;
        utmpl[i].daddr = tmpls[i].id.daddr;
        utmpl[i].proto = tmpls[i].id.proto;
        utmpl[i].sport = tmpls[i].sport;
        utmpl[i].dport = tmpls[i].dport;
        utmpl[i].dport_mask = tmpls[i].dport_mask;
        utmpl[i].sport_mask = tmpls[i].sport_mask;
    }

    count = nla_put(skb, XFRMA_TMPL, num_tmpls * sizeof(*utmpl), utmpl);
    kfree(utmpl);
    return count;
}

int copy_templates_to_skb(struct xfrm_policy *xp, struct sk_buff *skb) {
    struct xfrm_user_tmpl *utmp;
    int i, n = 0;

    if (!xp->xfrm_nr)
        return 0;

    n = xp->xfrm_nr * sizeof(struct xfrm_user_tmpl);
    utmp = kmemdup(xp->xfrm, n, GFP_ATOMIC);
    if (!utmp)
        return -ENOMEM;

    for (i = 0; i < xp->xfrm_nr; i++) {
        utmp[i].saddr = xp->xfrm[i].saddr;
        utmp[i].id = xp->xfrm[i].id;
        utmp[i].mode = xp->xfrm[i].mode;
        utmp[i].reqid = xp->xfrm[i].reqid;
        utmp[i].spi = xp->xfrm[i].spi;
        utmp[i].family = xp->xfrm[i].family;
        utmp[i].encap = xp->xfrm[i].encap;
        utmp[i].aalgo = xp->xfrm[i].aalgo;
        utmp[i].ealgo = xp->xfrm[i].ealgo;
        utmp[i].flags = xp->xfrm[i].flags;
        utmp[i].replay_window = xp->xfrm[i].replay_window;
        utmp[i].replay = xp->xfrm[i].replay;
    }

    nla_put(skb, XFRM_POLICY_Tmpl, n, utmp);
    kfree(utmp);

    return n;
}

