int copy_templates_to_skb(struct xfrm_policy *xp, struct sk_buff *skb) {
    struct xfrm_tmpl *tmpls = xp->xfrm_tmpl;
    int num_tmpls = xp->xfrm_num_tmpl;
    struct xfrm_user_tmpl *utmpl;
    int i, len = 0;

    if (!num_tmpls)
        return 0;

    utmpl = kcalloc(num_tmpls, sizeof(*utmpl), GFP_ATOMIC);
    if (!utmpl)
        return -ENOMEM;

    for (i = 0; i < num_tmpls; i++) {
        utmpl[i].mode = tmpls[i].mode;
        utmpl[i].reqid = tmpls[i].reqid;
        utmpl[i].saddr = tmpls[i].saddr;
        utmpl[i].prefixlen_s = tmpls[i].saddr_prefixlen;
        utmpl[i].prefixlen_d = tmpls[i].daddr_prefixlen;
        utmpl[i].family = tmpls[i].family;
    }

    len = nla_put(skb, XFRMA_TMPL, num_tmpls * sizeof(*utmpl), utmpl);
    kfree(utmpl);

    return len;
}

int copy_templates_to_skb(struct xfrm_policy *xp, struct sk_buff *skb)
{
    int i;
    int len = 0;
    struct xfrm_tmpl *tp;
    struct xfrm_user_tmpl *utp;

    if (!xp->xfrm_nr)
        return 0;

    for (i = 0; i < xp->xfrm_nr; i++) {
        tp = &xp->xfrm[i];
        utp = kmemdup(tp, sizeof(*utp), GFP_ATOMIC);
        if (!utp)
            return -ENOMEM;
        len += nla_put(skb, XFRMA_TMPL, sizeof(*utp), utp);
    }

    return len;
}

int copy_xfrm_templates(struct xfrm_policy *xp, struct sk_buff *skb)
{
    struct xfrm_user_tmpl *ut;
    struct xfrm_tmpl *tmplt;
    int ntmplt = 0;
    int i;

    if (hlist_empty(&xp->xfrm_tmpl))
        return 0;

    ntmplt = xp->xfrm_num_tmpl;

    ut = kcalloc(ntmplt, sizeof(*ut), GFP_ATOMIC);
    if (!ut)
        return -ENOMEM;

    i = 0;
    hlist_for_each_entry(tmplt, &xp->xfrm_tmpl, list) {
        ut[i].mode = tmplt->mode;
        ut[i].reqid = tmplt->reqid;
        ut[i].family = tmplt->family;
        ut[i].saddr = tmplt->saddr;
        ut[i].id.proto = tmplt->id.proto;
        ut[i].id.dport = tmplt->id.dport;
        ut[i].id.sport = tmplt->id.sport;
        ut[i].id.daddr = tmplt->id.daddr;
        ut[i].id.prefixlen_d = tmplt->id.prefixlen_d;
        ut[i].priority = tmplt->priority;
        i++;
    }

    nla_put(skb, XFRMA_TMPL, ntmplt * sizeof(*ut), ut);

    kfree(ut);
    return ntmplt * sizeof(*ut);
}
